package com.ribhlab.ribhmeasure;
import android.app.Activity;
import android.os.Bundle;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import android.text.*;
import java.util.Locale;
public final class RoomManualActivity extends Activity {
 EditText l,w,h; TextView answer; Plan plan; double length,width,height;
 String tr(String en,String fr,String ar){String x=getResources().getConfiguration().getLocales().get(0).getLanguage();return x.equals("ar")?ar:x.equals("fr")?fr:en;}
 int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
 @Override protected void attachBaseContext(android.content.Context base){super.attachBaseContext(Prefs.locale(base));}
 @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(20),dp(20),dp(20),dp(20));root.setBackgroundColor(0xff07111e);sc.addView(root);sc.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});TextView title=new TextView(this);title.setText(tr("Room plan","Plan de pièce","مخطط الغرفة"));title.setTextSize(26);title.setTextColor(0xffe5f4f4);root.addView(title);
 TextView hint=new TextView(this);hint.setText(tr("Enter real measured dimensions in metres. No camera or AR required.","Saisissez les dimensions mesurées en mètres. Sans caméra.","أدخل الأبعاد المقاسة بالمتر. لا تحتاج إلى الكاميرا."));hint.setTextColor(0xffa6d7d5);root.addView(hint);l=field(root,tr("Length (m)","Longueur (m)","الطول (م)"));w=field(root,tr("Width (m)","Largeur (m)","العرض (م)"));h=field(root,tr("Height (m)","Hauteur (m)","الارتفاع (م)"));plan=new Plan();root.addView(plan,new LinearLayout.LayoutParams(-1,dp(230)));answer=new TextView(this);answer.setTextSize(19);answer.setTextColor(0xffa7f9e8);root.addView(answer);Button save=new Button(this);save.setText(tr("Save room","Enregistrer","حفظ"));root.addView(save);save.setOnClickListener(v->{if(!calculate())return;Measurements.add(this,"Manual room area",length*width,"m²",answer.getText().toString());Toast.makeText(this,tr("Saved","Enregistré","تم الحفظ"),Toast.LENGTH_SHORT).show();});Button share=new Button(this);share.setText(tr("Share measurements","Partager","مشاركة القياسات"));root.addView(share);Button model=new Button(this);model.setText("2D / 3D / PDF");root.addView(model);model.setOnClickListener(v->{if(!calculate())return;android.content.Intent i=new android.content.Intent(this,RoomPlanActivity.class);i.putExtra("outline",new float[]{0,0,(float)length,0,(float)length,(float)width,0,(float)width});i.putExtra("height",height>0&&height<=1000?(float)height:Float.NaN);i.putExtra("manual",true);startActivity(i);});share.setOnClickListener(v->{if(!calculate())return;android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(android.content.Intent.EXTRA_TEXT,answer.getText().toString());startActivity(android.content.Intent.createChooser(i,tr("Share","Partager","مشاركة")));});TextWatcher tw=new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){calculate();}public void afterTextChanged(Editable e){}};l.addTextChangedListener(tw);w.addTextChangedListener(tw);h.addTextChangedListener(tw);setContentView(sc);calculate();}
 EditText field(LinearLayout root,String t){EditText e=new EditText(this);e.setHint(t);e.setTextColor(0xffffffff);e.setHintTextColor(0xff91aab8);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);root.addView(e,new LinearLayout.LayoutParams(-1,dp(60)));return e;}
 double number(EditText e){try{java.text.NumberFormat nf=java.text.NumberFormat.getNumberInstance(Locale.getDefault());String raw=e.getText().toString().trim();try{return Double.parseDouble(raw.replace(',','.'));}catch(NumberFormatException ex){return nf.parse(raw).doubleValue();}}catch(Exception ex){return 0;}}
 boolean calculate(){length=number(l);width=number(w);height=number(h);boolean ok=Double.isFinite(length)&&Double.isFinite(width)&&length>0&&width>0&&length<=1000&&width<=1000;plan.invalidate();if(!ok){answer.setText(tr("Enter valid length and width.","Saisissez longueur et largeur valides.","أدخل الطول والعرض بشكل صحيح."));return false;}String x=String.format(Locale.US,"%s: %.2f × %.2f m\n%s: %.2f m²\n%s: %.2f m",tr("Dimensions","Dimensions","الأبعاد"),length,width,tr("Floor area","Surface","المساحة"),length*width,tr("Perimeter","Périmètre","المحيط"),2*(length+width));if(height>0&&height<=1000)x+=String.format(Locale.US,"\n%s: %.2f m³\n%s: %.2f m²",tr("Volume","Volume","الحجم"),length*width*height,tr("Wall area (gross)","Murs (brut)","مساحة الجدران الإجمالية"),2*(length+width)*height);answer.setText(x);return true;}
 final class Plan extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);Plan(){super(RoomManualActivity.this);}@Override protected void onDraw(Canvas c){if(length<=0||width<=0||!Double.isFinite(length)||!Double.isFinite(width))return;float sc=(float)Math.min((getWidth()-dp(76))/length,(getHeight()-dp(60))/width);if(sc<=0)return;float x=(getWidth()-(float)length*sc)/2,y=(getHeight()-(float)width*sc)/2,r=x+(float)length*sc,b=y+(float)width*sc;p.setColor(0xff123c40);p.setStyle(Paint.Style.FILL);c.drawRect(x,y,r,b,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));p.setColor(0xff21e0c2);c.drawRect(x,y,r,b,p);p.setStyle(Paint.Style.FILL);p.setColor(0xffffffff);p.setTextSize(dp(15));c.drawText(String.format(Locale.US,"%.2f m",length),x,y-dp(8),p);c.save();c.rotate(-90,x-dp(9),b);c.drawText(String.format(Locale.US,"%.2f m",width),x-dp(9),b,p);c.restore();}}
}
